<?php require_once __DIR__.'/includes/bootstrap.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){redirect('/dashboard.php');}verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$s=$pdo->prepare('DELETE FROM events WHERE id=? AND user_id=?');$s->execute([$id,$_SESSION['user_id']]);flash($s->rowCount()?'success':'error',$s->rowCount()?'Event deleted successfully.':'Event not found or you do not have permission to delete it.');redirect('/dashboard.php');